from cfg.parser import parse


def test_basic():
    assert parse("[a]\nx = 1\n") == {"": {}, "a": {"x": "1"}}


def test_inline_comments():
    text = "[a]\nx = 1 # comment\ny = 2 ; comment\nz = 3#nospace\n"
    assert parse(text) == {"": {}, "a": {"x": "1", "y": "2", "z": "3#nospace"}}


def test_quoted_values_protect_chars():
    assert parse('[a]\nx = "a#b=c"\n') == {"": {}, "a": {"x": "a#b=c"}}
    assert parse('[a]\nx = "v # keep" # drop\n') == {"": {}, "a": {"x": "v # keep"}}


def test_repeated_keys_last_wins():
    assert parse("[a]\nk = 1\nk = 2\nK = 3\n") == {"": {}, "a": {"k": "3"}}

